def transform(grid):
    rows = len(grid)
    if rows == 0:
        return grid
    cols = len(grid[0])
    output = [row[:] for row in grid]

    for r in range(rows):
        # Check for stable condition based on demo logic:
        # If the last cell is not 1, the row remains unchanged (stable).
        # Note: In the demo, stable rows had a non-1 at the last column.
        # Modified rows had a non-1 somewhere else, and 1 at the last column.
        # If last cell is not 1 (stable), skip.
        if grid[r][cols - 1] != 1:
            continue

        # Find the seed (first non-1 value) in the row
        seed_idx = -1
        seed_val = -1
        for c in range(cols):
            if grid[r][c] != 1:
                seed_idx = c
                seed_val = grid[r][c]
                break

        if seed_idx == -1:
            # No seed found, likely stays as 1s
            continue

        # Apply transformation from seed_idx to end
        for c in range(seed_idx, cols):
            offset = c - seed_idx
            if offset % 2 == 0:
                output[r][c] = seed_val
            else:
                output[r][c] = 5

    return output
